<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><title><?= Auth::escape(Auth::pageTitle('Journaux')) ?></title>
