<header><div class="h5ai-header-leading"><a class="h5ai-back-link" href="<?= Auth::escape($home) ?>" aria-label="Retour aux fichiers" title="Retour aux fichiers"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 5-7 7 7 7M5 12h14"/></svg></a><h1>Journaux</h1></div><div class="h5ai-header-actions"><div id="h5ai-account-slot"><?php require __DIR__ . '/logout-control.php'; ?></div></div></header>
