<?php if ($error !== '') { ?><p class="alert" role="alert"><?= Auth::escape($error) ?></p><?php } ?>
<?php if ($history['write_error']) { ?><p class="alert" role="alert">L’enregistrement de nouveaux événements est indisponible. L’historique peut être incomplet ; vérifiez les permissions et l’espace disponible du stockage privé.</p><?php } ?>
<?php if ($history['quota']) { ?><p class="alert" role="alert">La limite de volume des journaux a été atteinte sur au moins une journée conservée. Certains événements de ces journées peuvent manquer.</p><?php } ?>
<?php if ($history['warnings']) { ?><p class="alert" role="alert">Certaines lignes de journal sont invalides et ont été ignorées.</p><?php } ?>
<form class="filters" method="get" action="<?= Auth::escape(Routes::url('logs')) ?>">
<label>Du<input type="date" name="from" value="<?= Auth::escape($filter['from_text']) ?>" required></label>
<label>Au<input type="date" name="to" value="<?= Auth::escape($filter['to_text']) ?>" required></label>
<label>Utilisateur<input name="user" value="<?= Auth::escape($filter['user']) ?>" list="audit-users" placeholder="Tous les comptes" maxlength="128" autocomplete="off"></label>
<datalist id="audit-users"><?php foreach ($users as $user) { ?><option value="<?= Auth::escape((string) $user) ?>"><?php } ?></datalist>
<label>Événement<select name="event"><option value="">Tous les événements</option><?php foreach ($events as $key => $label) { ?><option value="<?= Auth::escape($key) ?>" <?= $filter['event'] === $key ? 'selected' : '' ?>><?= Auth::escape($label) ?></option><?php } ?></select></label>
<label>Résultat<select name="result"><option value="">Tous les résultats</option><?php foreach (['success' => 'Réussite', 'failure' => 'Échec', 'denied' => 'Refusé'] as $key => $label) { ?><option value="<?= $key ?>" <?= $filter['result'] === $key ? 'selected' : '' ?>><?= $label ?></option><?php } ?></select></label>
<div class="filter-actions"><button type="submit">Filtrer</button><a href="<?= Auth::escape(Routes::url('logs')) ?>">Réinitialiser</a></div></form>
<div class="table-wrap"><table><thead><tr><th>Date et heure</th><th>Événement</th><th>Auteur</th><th>Compte concerné</th><th>Adresse IP</th><th>Résultat</th><th>Détails</th></tr></thead><tbody>
<?php foreach ($history['rows'] as $row) { $date = (new DateTimeImmutable('@' . $row['time']))->setTimezone($timezone); ?>
<tr data-event-id="<?= Auth::escape($row['id']) ?>"><td class="date"><time datetime="<?= gmdate('c', $row['time']) ?>"><?= $date->format('d/m/Y H:i:s') ?></time></td><td><?= Auth::escape($events[$row['event']]) ?></td><td><?= Auth::escape($row['actor'] ?? '—') ?></td><td><?= Auth::escape($row['target'] ?? '—') ?></td><td class="ip"><?= Auth::escape($row['ip'] ?? '—') ?><small><?= $row['ip_source'] === 'proxy' ? 'Client via proxy de confiance' : 'Adresse réseau directe' ?></small></td><td><span class="result <?= $row['result'] ?>"><?= ['success' => 'Réussite', 'failure' => 'Échec', 'denied' => 'Refusé'][$row['result']] ?></span></td><td class="details"><?= Auth::escape(Journal::description($row['details'])) ?></td></tr>
<?php } ?>
<?php if (!$history['rows']) { ?><tr><td colspan="7" class="empty">Aucun événement pour ces filtres.</td></tr><?php } ?>
</tbody></table></div>
<nav class="pagination" aria-label="Pages des journaux"><?php if ($filter['page'] > 1) { ?><a class="button" rel="prev" href="<?= Auth::escape(Journal::pageUrl($filter, $filter['page'] - 1)) ?>">Précédent</a><?php } ?><span>Page <?= $filter['page'] ?></span><?php if ($history['next']) { ?><a class="button" rel="next" href="<?= Auth::escape(Journal::pageUrl($filter, $filter['page'] + 1)) ?>">Suivant</a><?php } ?></nav>
<p class="hint">Le filtre utilisateur recherche l’auteur ou le compte concerné, y compris les comptes renommés ou supprimés. Une IP de proxy peut apparaître si aucun proxy de confiance n’est configuré.</p></main></body></html>
